#!/bin/bash
# SessionStart orchestrator — the ONE place the corpus-dependent session-start
# steps run, IN SEQUENCE, in a single process.
#
# Why this exists: Claude Code runs hook entries IN PARALLEL with
# non-deterministic order ("all matching hooks run in parallel… the order is
# non-deterministic" — the Claude Code hooks docs). So a populate-then-read
# chain spread across separate SessionStart entries is a race, not a sequence —
# the cause of intermittent "the harness didn't load this session" reports.
# Everything that reads the corpus therefore runs HERE, in order. The corpus is
# always already present: a consumer's tracked vendored mount, or the canon
# checkout itself.
#
# Each step's stdout is forwarded to this hook's stdout, which SessionStart adds
# to the session context (a pack's own session-start step, halt-and-ask directives,
# the summary line) — everything a session can only learn at session time. Static pack
# prose is NOT here and must not come back: it rides CLAUDE.md, on a channel that does
# not truncate (#807, and the missing step above).
# Progress — a timestamp and what it is doing — is written to .claudinite-hooks.log and to
# stderr, so a triggering failure (no lines at all) reads differently from an
# execution failure (a step logged `start` but not `done`).
#
# Always exits 0: a SessionStart hook cannot block, and a non-zero exit makes
# Claude Code DISCARD this hook's stdout — including any step's halt-and-ask
# directive, the load-bearing safety gate. Failure is surfaced via the log and
# the injected directives, never the exit code.
set -uo pipefail
here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"  # <corpus>/engine/hooks
# This script lives in <corpus>/engine/hooks/; every step script it runs lives in
# the engine's loader dir (<corpus>/engine/pack_loader), except the self-test at
# the engine root.
corpus="$(dirname "$(dirname "$here")")"

# --- durable hook log (format mirrored in engine/checks/helpers/hook-log.mjs —
# --- keep the two in step). Lives at the project
# --- root, OUTSIDE .claudinite/, beside the repo's own files. Best
# --- effort: logging must never fail a hook.
CLAUDINITE_LOG="${CLAUDE_PROJECT_DIR:-.}/.claudinite-hooks.log"
CLAUDINITE_HOOK_RUN="${CLAUDINITE_HOOK_RUN:-$$}"; export CLAUDINITE_HOOK_RUN
# Bound the log across sessions (no-op when a Method B sync already trimmed it).
if [ -f "$CLAUDINITE_LOG" ] && [ "$(wc -c <"$CLAUDINITE_LOG" 2>/dev/null || echo 0)" -gt 262144 ]; then
  tail -n 400 "$CLAUDINITE_LOG" >"$CLAUDINITE_LOG.tmp" 2>/dev/null && mv "$CLAUDINITE_LOG.tmp" "$CLAUDINITE_LOG" 2>/dev/null || true
fi
hooklog() {
  local ts; ts="$(date -u +%Y-%m-%dT%H:%M:%SZ 2>/dev/null || echo '?')"
  local line="$ts run=$CLAUDINITE_HOOK_RUN $1: $2"
  printf '%s\n' "$line" >>"$CLAUDINITE_LOG" 2>/dev/null || true
  printf '%s\n' "$line" >&2 2>/dev/null || true
}

# Run one step, forwarding its stdout to ours (→ session context) and logging
# its lifecycle. A step failing (they fail soft) never aborts the rest — hence
# no `set -e`. Tallies feed the one-line confirmation footer below.
ran=0; labels=""; warns=""
run_step() {
  local label="$1"; shift
  hooklog "$label" "start"
  "$@"
  local rc=$?
  hooklog "$label" "done exit=$rc"
  ran=$((ran + 1))
  labels="${labels:+$labels, }$label"
  [ "$rc" -ne 0 ] && warns="${warns:+$warns; }$label exited $rc"
}

# The facet channel: a scratch file the pack session-start steps append one short
# phrase each to, and the summary step folds into the line it emits. Created here
# because the orchestrator is what both ends have in common; a session where mktemp
# fails simply has no channel, and every step still runs.
CLAUDINITE_SESSION_FACETS="$(mktemp 2>/dev/null || true)"; export CLAUDINITE_SESSION_FACETS
cleanup() { [ -n "${CLAUDINITE_SESSION_FACETS:-}" ] && rm -f "$CLAUDINITE_SESSION_FACETS" 2>/dev/null || true; }
trap cleanup EXIT

# The repo-local git config the `merge=ours` .gitattributes entries and conflict
# replay need. It converges here, not in the environment Setup script, because it
# is per-CLONE state: a fresh checkout — every terminal clone, and a web session
# whose container re-clones — carries none of it however the image was built.
git_config() {
  local d="${CLAUDE_PROJECT_DIR:-.}"
  if ! git -C "$d" rev-parse --git-dir >/dev/null 2>&1; then
    hooklog git-config "no git repo at $d — nothing to configure"
    return 0
  fi
  git -C "$d" config merge.ours.driver true && git -C "$d" config rerere.enabled true
}

hooklog orchestrator "start"
run_step git-config git_config
# BEFORE EVERYTHING THAT READS THE SESSION'S PACK SET. A pack may COPY another pack into
# the session - content belonging to the person in front of it rather than to the
# repository, which no tracked tree can carry. The mount below, the self-test after it and
# the rules index all read that set, so a copy arriving later is a copy nothing sees.
#
# NOTHING IT PRINTS IS SESSION CONTEXT, which is why this is the one step whose stdout is
# redirected: a prepare step is doing something, not saying something, and what it has to
# say reaches the session through the step that runs in the reporting phase. The redirect
# is here rather than left to the runner because this is where the channel is decided, and
# a step that wrote to the wrong one would spend the session's context without anyone
# choosing to.
pack_session_prepare() { node "$corpus/engine/pack_loader/run-pack-session-start.mjs" --prepare >&2; }
run_step pack-session-prepare pack_session_prepare
# CONVERGE BEFORE REPORTING. This step regenerates the .claude/skills mounts to match
# the declared packs, and the self-test below judges those same links — so running it
# first is what makes that judgment true of the session the person actually gets. The
# other way round, a resume whose mounts had gone stale reported dangling links that
# the same firing repaired a second later, under a "re-run the skill mount" remedy
# that had already run (#875). It costs the report nothing: this step writes no
# stdout, so the self-test still LEADS the injected context either way.
run_step mount-skills       node "$corpus/engine/pack_loader/mount-skills.mjs"
# FIRST OF THE REPORTING STEPS, and report-only: "can Claudinite run here?" — the
# mount, the stamp, the pack manifests, the hook targets, the mounted skills, the
# cron, the migrations registry. It leads the steps whose dependencies it judges, so
# its output explains their failures rather than trailing them. Never `--strict`
# here: a non-zero exit makes Claude Code DISCARD this hook's stdout, which would
# throw away the very report it exists to deliver (and any halt directive with it).
run_step selftest           node "$corpus/engine/selftest.mjs"
# NO PROSE STEP. The active packs' RULES.md used to be emitted here, and #807 measured
# what that cost: 79,750 of this hook's 82,267 bytes, silently truncated to a ~2KB
# preview on the way into a live session, with no signal back either way. The corpus
# now reaches a session through `.claudinite/flat/claudinite-rules.GENERATED.md`, imported
# by the repo's CLAUDE.md, which the harness loads in full
# (engine/pack_loader/generate-rules-index.mjs). What is left here is what only a
# session can compute — which is the test for anything proposed for this hook.
# What a pack can only know at session time:
# each active pack's own session-start.mjs, run and forwarded into context. Core
# never learns what one does — the SessionEnd runner's terms, at the other end of
# the session.
run_step pack-session-start node "$corpus/engine/pack_loader/run-pack-session-start.mjs"
run_step env-check          node "$corpus/engine/pack_loader/env-requirements.mjs" check
# The interview machinery is the adoption skill's, bundled in the
# Claudinite-lifecycle pack — absent when the tree doesn't carry it, and then
# there is no interview.
interview="$corpus/packs/claudinite-lifecycle/skills/adopt-claudinite/interview.mjs"
[ -f "$interview" ] && run_step interview-check node "$interview" check
# LAST, and about the session rather than the machinery: the one line stating what
# loaded — the packs, their checks, the token weight of their prose, the skills, and
# whatever the steps above said on the facet channel. It runs after them so it
# describes the session that exists rather than the one about to.
# Guarded on the file, like the interview: a mount converging mid-flight can hold
# this orchestrator before it holds the step, and a missing step is a summary the
# session goes without, not a warning about the session's own machinery.
summary_step="$corpus/engine/pack_loader/session-summary.mjs"
[ -f "$summary_step" ] && run_step session-summary node "$summary_step"
hooklog orchestrator "done"

# One terse, visible confirmation into the session context that the harness ran
# this session — the healthy-case counterpart to the loud halt directives. It
# reports that the machinery ran (not that every step succeeded semantically — a
# soft halt still exits 0), and flags any step that actually crashed.
end_ts="$(date -u +%Y-%m-%dT%H:%M:%SZ 2>/dev/null || echo '?')"
summary="Claudinite session-start: ran $ran steps ($labels) at $end_ts."
[ -n "$warns" ] && summary="$summary WARNING: $warns."
printf '%s\n' "$summary"
exit 0
#!/usr/bin/env node
// The Claudinite SELF-TEST — "can Claudinite run here?", and nothing else.
//
// Deliberately NOT a conformance check. `check_the_world` judges the repo's
// CONTENT against the rules; this judges whether the MACHINERY that would run
// those rules is intact. A repo can be perfectly conformant and still have a
// broken mount, a hook pointing at a file that no longer exists, or a pack whose
// manifest the loader silently drops — and every one of those is invisible to a
// content check, because a rule that never runs reports nothing.
//
// WHY IT EXISTS. Every fleet-wide failure this corpus has had was of that shape:
//
//   #397  inject-pack-prose imported a module that did not exist, so every
//         active pack's RULES.md was silently un-injected, fleet-wide, for days
//   #518  loadConfig dropped the mount stamp, so the nightly converge self-skipped
//         everywhere and no run ever said so
//   #555  a required manifest field landed with no migration; consumer packs
//         stopped validating, and (because normalizeManifest rebuilds `rules`
//         from the scoped lists) their checks stopped running silently
//   #424  five mounted skill links dangled on main, unnoticed
//
// None was caught by canon CI, because the canon's own tree is always already
// correct. All four are assertions below, and each would have fired on the first
// session after the change — on the member, where the damage was.
//
// CONTRACT. Fast (no network, no clone), read-only, and it never throws: a probe
// that cannot run is a FAILED probe with the reason attached, never a crash that
// takes the session-start orchestrator down with it.
//
// Pure core + thin I/O shell, the corpus idiom: `report()` takes plain probe
// results and decides the outcome, so the whole decision surface is testable
// without a repo on disk.

import { existsSync, readFileSync, readdirSync, lstatSync, realpathSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { SETTINGS_FILE } from './settings-file.mjs';
import { hasInstalledMount } from './installed-versions.mjs';

export const MOUNT = '.claudinite/shared';
// Both settings-file names, newest first (#1252): the probe runs on a member whose
// own rename record may not have landed yet, and reporting "the declaration is
// missing" on a repo that simply spells it the old way would fail every session
// there over a file sitting right beside it.
export const CHECKS = SETTINGS_FILE;
export const SETTINGS = '.claude/settings.json';
export const SCHEDULER = '.github/workflows/claudinite-scheduler.yml';

// A probe result. `ok: null` means NOT APPLICABLE — the thing this probe would
// judge is legitimately absent (no scheduler in a repo that never cut over, no
// local packs declared). Not-applicable is never a failure; conflating the two
// is how a check earns its reputation for crying wolf.
export const pass = (id) => ({ id, ok: true });
export const skip = (id, why) => ({ id, ok: null, detail: why });
export const fail = (id, detail, fix) => ({ id, ok: false, detail, fix });

// The verdict over a probe set. Exit code is the caller's business — this only
// says what happened, so both callers (a session-start step that must never
// block, and a strict CI/bootstrap run that must) read the same result.
export function report(probes) {
  const failures = probes.filter((p) => p.ok === false);
  const ran = probes.filter((p) => p.ok !== null).length;
  return {
    ok: failures.length === 0,
    ran,
    skipped: probes.length - ran,
    failures,
    summary: failures.length
      ? `Claudinite self-test: ${failures.length} of ${ran} probes FAILED — ${failures.map((f) => f.id).join(', ')}`
      : `Claudinite self-test: ${ran} probes passed.`,
  };
}

// --- the probes ------------------------------------------------------------
// Each takes an injected `io` ({ exists, read, dirs, resolves }) so the whole
// set runs against an in-memory tree in tests. No probe imports another's
// result: a broken mount must not cascade into eight confusing failures, so
// each says one true thing about the repo in front of it.

export function probeMount(io) {
  if (!io.exists(MOUNT)) return skip('mount', 'no vendored mount — this is the canon itself, or a repo that has not adopted');
  if (!io.exists(`${MOUNT}/engine/checks/check_the_world.mjs`)) {
    return fail('mount', `${MOUNT} exists but carries no engine`, 're-run the update task, or bootstrap this repo — the mount is incomplete');
  }
  return pass('mount');
}

export function probeStamp(io) {
  const raw = io.read(CHECKS);
  if (raw === null) return fail('stamp', `${CHECKS} is missing`, 'run bootstrap --init to write the declaration');
  let cfg;
  try { cfg = JSON.parse(raw); } catch (e) {
    return fail('stamp', `${CHECKS} is not valid JSON: ${e.message}`, 'fix the JSON syntax - nothing can read the declaration until it parses');
  }
  if (!io.exists(MOUNT)) return skip('stamp', 'no vendored mount to stamp');
  // The VERSIONS, not a datetime. The `claudinite.updated` this probed until #1252
  // recorded the last full re-vendor rather than the last converge, so it was a
  // stale reading of a healthy mount; what the update flows actually read to decide
  // what to apply is what a member has installed, which is what must be present.
  if (!hasInstalledMount(cfg)) {
    return fail('stamp', 'the mount is present but no installed versions are recorded',
      'the update flows read these to decide what to apply — with none, the task self-skips forever (#518)');
  }
  return pass('stamp');
}

// The #555 probe. A manifest the loader rejects means that pack's rules never
// run — silently, because normalizeManifest rebuilds `rules` from the scoped
// lists and an unvalidated manifest contributes none.
export function probePackManifests(loaded) {
  if (!loaded) return skip('pack-manifests', 'the pack loader could not be reached from here');
  if (loaded.errors?.length) {
    const first = loaded.errors[0];
    return fail('pack-manifests', `${loaded.errors.length} pack(s) failed to load or validate — first: ${first.what ?? first}`,
      first.fix ?? 'fix the manifest — a pack that does not validate contributes no rules, so its checks stop running with no other symptom');
  }
  if (!loaded.packs?.length) return fail('pack-manifests', 'no packs were discovered at all', 'check the mount and the declaration — a session with no packs enforces nothing');
  return pass('pack-manifests');
}

export function probeHookTargets(io) {
  const raw = io.read(SETTINGS);
  if (raw === null) return skip('hook-targets', 'no .claude/settings.json');
  let cfg;
  try { cfg = JSON.parse(raw); } catch (e) {
    return fail('hook-targets', `${SETTINGS} is not valid JSON: ${e.message}`, 'fix the JSON — the harness silently runs no hooks when its settings will not parse');
  }
  const missing = [];
  for (const entries of Object.values(cfg.hooks ?? {})) {
    for (const entry of Array.isArray(entries) ? entries : []) {
      for (const hook of entry.hooks ?? []) {
        const cmd = String(hook.command ?? '');
        // The path inside the command, with the harness's variable resolved.
        const m = cmd.match(/\$CLAUDE_PROJECT_DIR\/(\S+)/);
        if (m && !io.exists(m[1])) missing.push(m[1]);
      }
    }
  }
  if (missing.length) {
    return fail('hook-targets', `${missing.length} hook command(s) point at files that do not exist: ${missing.join(', ')}`,
      're-run the update task to converge the wiring — a hook whose target is missing fails silently every session (#397)');
  }
  return pass('hook-targets');
}

export function probeSkillLinks(io) {
  const root = '.claude/skills';
  if (!io.exists(root)) return skip('skill-links', 'no mounted skills');
  const dangling = io.dangling(root);
  if (dangling.length) {
    return fail('skill-links', `${dangling.length} mounted skill link(s) dangle: ${dangling.slice(0, 5).join(', ')}`,
      're-run the skill mount (the update task does it) — a dangling link is a skill the session cannot load (#424)');
  }
  return pass('skill-links');
}

export function probeScheduler(io) {
  const text = io.read(SCHEDULER);
  if (text === null) return skip('scheduler', 'no vendored scheduler workflow — this repo has not cut over to per-project scheduling');
  const crons = [...text.matchAll(/cron:\s*['"]?([^'"\n]+?)['"]?\s*$/gm)].map((m) => m[1].trim());
  if (crons.length !== 1) {
    return fail('scheduler', `the scheduler declares ${crons.length} cron schedules, expected exactly one`, 'keep a single hourly cron — the scheduler is the repo\'s only cron');
  }
  const parts = crons[0].split(/\s+/);
  if (parts.length !== 5 || !Number.isInteger(Number(parts[0]))) {
    return fail('scheduler', `the scheduler cron "${crons[0]}" does not parse as a 5-field expression with a fixed minute`,
      'set "<minute> * * * *" with the repo-hashed minute — an unparseable cron means the repo never runs a task again');
  }
  return pass('scheduler');
}

export function probeMigrations(migrations) {
  if (migrations === null) return skip('migrations', 'no migrations registry reachable from here');
  if (migrations instanceof Error) {
    return fail('migrations', `the migrations registry failed to load: ${migrations.message}`,
      'a malformed record aborts every update run — fix or remove it');
  }
  return pass('migrations');
}

// --- the I/O shell ---------------------------------------------------------

function makeIo(root) {
  const abs = (p) => join(root, p);
  return {
    exists: (p) => existsSync(abs(p)),
    read: (p) => { try { return readFileSync(abs(p), 'utf8'); } catch { return null; } },
    // Symlinks under a directory whose targets do not resolve.
    dangling: (rel) => {
      const out = [];
      const walk = (dir) => {
        let entries = [];
        try { entries = readdirSync(abs(dir), { withFileTypes: true }); } catch { return; }
        for (const e of entries) {
          const p = `${dir}/${e.name}`;
          if (e.isSymbolicLink()) {
            try { realpathSync(abs(p)); } catch { out.push(p); }
          } else if (e.isDirectory()) walk(p);
        }
      };

